// Disconnected entity
var std = new Student() { Name = "Bill" };

using (var context = new SchoolContext())
{
    // 1. Attach entity with Added state
    context.Add<Student>(std);

    // or: context.Students.Add(std);
    // or: context.Entry<Student>(std).State = EntityState.Added;
    // or: context.Attach<Student>(std);

    // 2. Save to database
    context.SaveChanges();
}

var stdAddress = new StudentAddress()
{
    City = "SFO",
    State = "CA",
    Country = "USA"
};

var std = new Student()
{
    Name = "Steve",
    Address = stdAddress
};

using (var context = new SchoolContext())
{
    context.Add<Student>(std);
    context.SaveChanges();
}

var studentList = new List<Student>() {
    new Student(){ Name = "Bill" },
    new Student(){ Name = "Steve" }
};

using (var context = new SchoolContext())
{
    context.AddRange(studentList);
    context.SaveChanges();
}
